// Extract data from webhook
const { itinerary, name, email, generatedAt } = $input.first().json;

// Generate HTML for PDF
const html = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { 
      font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; 
      max-width: 800px; 
      margin: 0 auto; 
      padding: 40px 20px; 
      color: #1f2937; 
      line-height: 1.6;
    }
    .header { 
      text-align: center; 
      margin-bottom: 30px; 
      padding-bottom: 20px;
      border-bottom: 3px solid #2563eb;
    }
    h1 { 
      color: #2563eb; 
      font-size: 28px;
      margin-bottom: 10px;
    }
    .meta { color: #6b7280; font-size: 14px; }
    .summary { 
      background: linear-gradient(135deg, #eff6ff 0%, #dbeafe 100%); 
      padding: 20px; 
      border-radius: 12px; 
      margin: 25px 0;
      border-left: 4px solid #2563eb;
    }
    .day { 
      margin: 30px 0; 
      page-break-inside: avoid;
    }
    .day-header { 
      background: #2563eb;
      color: white;
      padding: 12px 20px; 
      border-radius: 8px 8px 0 0;
      font-size: 18px; 
      font-weight: 600;
    }
    .day-content {
      border: 1px solid #e5e7eb;
      border-top: none;
      border-radius: 0 0 8px 8px;
      padding: 15px;
    }
    .activity { 
      margin: 15px 0; 
      padding: 15px; 
      background: #fafafa; 
      border-radius: 8px;
      border-left: 3px solid #10b981;
    }
    .activity-time { 
      font-weight: 700; 
      color: #2563eb; 
      font-size: 14px;
      margin-bottom: 5px;
    }
    .activity-name { 
      font-size: 17px; 
      font-weight: 600; 
      color: #1f2937;
      margin-bottom: 8px;
    }
    .activity-desc { 
      color: #4b5563; 
      font-size: 14px; 
      margin-bottom: 8px;
    }
    .activity-meta {
      display: flex;
      gap: 15px;
      font-size: 13px;
      color: #6b7280;
    }
    .tip { 
      background: #fef3c7; 
      padding: 10px 15px; 
      border-radius: 6px; 
      font-size: 13px; 
      margin-top: 10px;
      border-left: 3px solid #f59e0b;
    }
    .travel { 
      text-align: center; 
      padding: 10px; 
      color: #6b7280;
      font-size: 13px;
    }
    .travel-icon { font-size: 16px; }
    .footer { 
      margin-top: 40px; 
      padding-top: 20px; 
      border-top: 2px solid #e5e7eb; 
      color: #6b7280; 
      font-size: 12px;
      text-align: center;
    }
    .sources { 
      background: #f9fafb; 
      padding: 15px; 
      border-radius: 8px; 
      margin-top: 15px;
    }
    .sources-title { font-weight: 600; margin-bottom: 8px; }
  </style>
</head>
<body>
  <div class="header">
    <h1>${itinerary.title}</h1>
    <p class="meta">Prepared for <strong>${name}</strong></p>
    <p class="meta">${itinerary.tripDates}</p>
  </div>

  <div class="summary">
    <strong>Trip Overview:</strong> ${itinerary.summary}
  </div>

  ${itinerary.days.map(day => `
    <div class="day">
      <div class="day-header">Day ${day.dayNumber} - ${day.date}</div>
      <div class="day-content">
        ${day.activities.map((activity, idx) => `
          ${activity.travelTime ? `<div class="travel"><span class="travel-icon">🚗</span> ${activity.travelTime}</div>` : ''}
          <div class="activity">
            <div class="activity-time">${activity.time}</div>
            <div class="activity-name">${activity.name}</div>
            <div class="activity-desc">${activity.description}</div>
            <div class="activity-meta">
              <span>⏱️ ${activity.duration}</span>
            </div>
            ${activity.tips && activity.tips.length > 0 ? `<div class="tip">💡 <strong>Tip:</strong> ${activity.tips[0]}</div>` : ''}
          </div>
        `).join('')}
      </div>
    </div>
  `).join('')}

  <div class="footer">
    <div class="sources">
      <div class="sources-title">📚 Sources</div>
      ${itinerary.sources.join(' • ')}
    </div>
    <p style="margin-top: 15px;">Generated on ${new Date(generatedAt).toLocaleString('en-IN', { dateStyle: 'full', timeStyle: 'short' })}</p>
    <p style="margin-top: 5px;">Created with ❤️ by Ooty Trip Planner</p>
  </div>
</body>
</html>
`;

return {
  html,
  email,
  name,
  subject: `Your ${itinerary.title} is Ready!`,
  tripDates: itinerary.tripDates
};
